var gameplay=GameObject.Find("NewMap Gameplay");var old=gameplay.GetComponent<Unity.AI.Navigation.NavMeshSurface>();var data=old.navMeshData;old.RemoveData();UnityEngine.Object.DestroyImmediate(old);var nav=new GameObject("NewMap Navigation");nav.transform.SetParent(gameplay.transform,true);nav.transform.position=Vector3.zero;nav.transform.rotation=Quaternion.identity;var surface=nav.AddComponent<Unity.AI.Navigation.NavMeshSurface>();surface.agentTypeID=-1372625422;surface.navMeshData=data;surface.AddData();var filter=new UnityEngine.AI.NavMeshQueryFilter{agentTypeID=-1372625422,areaMask=-1};var path=new UnityEngine.AI.NavMeshPath();var spawn=UnityEngine.Object.FindObjectOfType<WaveManager>().spawnPoint;var goal=UnityEngine.Object.FindObjectOfType<Base>().transform;UnityEngine.AI.NavMeshHit a,b;bool aa=UnityEngine.AI.NavMesh.SamplePosition(new Vector3(-16.7f,.1f,-16.85f),out a,3,filter);bool bb=UnityEngine.AI.NavMesh.SamplePosition(new Vector3(26.94f,.1f,16.32f),out b,3,filter);spawn.position=a.position;goal.position=b.position;UnityEngine.AI.NavMesh.CalculatePath(spawn.position,goal.position,filter,path);UnityEditor.SceneManagement.EditorSceneManager.SaveScene(gameplay.scene);return new{aa,bb,status=path.status.ToString(),corners=path.corners.Select(p=>p.ToString()).ToArray()};
